+            placeholder="e.g. (555) 123-4567"
+          >
+          <p id="phone-help" class="helper-text">Expected format: 10 digits, with optional spaces, dashes, or parentheses.</p>
+          <p id="phone-error" class="error-message" aria-live="polite"></p>
