+        <p id="form-status" class="status-message" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('support-form');
+    const fields = {
+      fullName: {
+        input: document.getElementById('full-name'),
+        error: document.getElementById('full-name-error'),
+        validate(value) {
+          if (!value.trim()) {
+            return 'Full name is required.';
+          }
+          return '';
+        }
+      },
+      email: {
+        input: document.getElementById('email'),
+        error: document.getElementById('email-error'),
+        validate(value) {
+          if (!value.trim()) {
+            return 'Email address is required.';
+          }
+          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
+            return 'Enter a valid email address.';
+          }
+          return '';
+        }
+      },
+      phone: {
+        input: document.getElementById('phone'),
+        error: document.getElementById('phone-error'),
+        validate(value) {
+          const trimmedValue = value.trim();
+          if (!trimmedValue) {
+            return '';
+          }
+
+          const digitsOnly = trimmedValue.replace(/\D/g, '');
+          if (digitsOnly.length !== 10) {
+            return 'Enter a 10-digit phone number or leave this field blank.';
+          }
