         validate(value) {
           if (!value.trim()) {
             return 'Email address is required.';
           }
           if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
             return 'Enter a valid email address.';
           }
           return '';
         }
       },
       phone: {
         input: document.getElementById('phone'),
         error: document.getElementById('phone-error'),
         validate(value) {
           const trimmedValue = value.trim();
           if (!trimmedValue) {
             return '';
           }

           const digitsOnly = trimmedValue.replace(/\D/g, '');
           if (digitsOnly.length !== 10) {
             return 'Enter a 10-digit phone number or leave this field blank.';
           }

           if (!/^[()\-\s\d]+$/.test(trimmedValue)) {
             return 'Use only digits, spaces, dashes, or parentheses.';
           }

           return '';
         }
       }
     };

     const formStatus = document.getElementById('form-status');

     function setFieldError(field, message) {
       field.error.textContent = message;
       field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
     }

     function validateField(fieldConfig) {
       const message = fieldConfig.validate(fieldConfig.input.value);
       setFieldError(fieldConfig, message);
       return !message;
     }

     Object.values(fields).forEach((field) => {
       field.input.addEventListener('input', () => {
         validateField(field);
         if (formStatus.textContent) {
           formStatus.textContent = '';
         }
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       formStatus.textContent = '';

       let firstInvalidField = null;

       Object.values(fields).forEach((field) => {
         const isValid = validateField(field);
         if (!isValid && !firstInvalidField) {
           firstInvalidField = field.input;
         }
       });

       if (firstInvalidField) {
         firstInvalidField.focus();
         return;
       }

       formStatus.textContent = 'Your support request is ready to send.';
       form.reset();
       Object.values(fields).forEach((field) => setFieldError(field, ''));
     });
   </script>
 </body>
 </html>
